### 📋 Complete Secure App.js Example

```javascript
// ✅ SECURE VERSION
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const app = express();

// 1. Environment validation
if (!process.env.JWT_SECRET) {
  throw new Error('JWT_SECRET is required');
}

// 2. Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// 4. Authentication middleware
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// 5. Public endpoint (rate-limited separately)
app.get('/health', rateLimit({ windowMs: 60000, max: 30 }), (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6. Protected endpoint
app.get('/users', authMiddleware, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Remove sensitive data for non-admins
  if (req.user.role !== 'admin') {
    return res.json(users.map(u => ({ id: u.id, name: u.name })));
  }

  res.json(users);
});

// 7. Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error'
    : err.message;

  res.status(statusCode).json({ error: message });
});

// 8. Listen securely
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

module.exports = app;
```

