```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// Environment configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.CORS_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// 4. Logging
app.use(morgan('combined'));

// 5. Body Parser
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 6. Authentication Middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ message: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ message: 'Invalid or expired token' });
  }
};

// 7. Health Check (Public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// 8. Protected Routes
app.get('/users', authenticateToken, (req, res) => {
  try {
    // Users can only see their own data, or admins can see all
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter based on user permissions
    if (req.user.role !== 'admin') {
      const userUsers = users.filter(u => u.id === req.user.id);
      return res.json(userUsers);
    }

    res.json(users);
  } catch (err) {
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

// 9. 404 Handler
app.use((req, res) => {
  res.status(404).json({ message: 'Not Found' });
});

// 10. Global Error Handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    timestamp: new Date().toISOString(),
    path: req.path
  });

  const status = err.status || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({ message });
});

// 11. Start Server
app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;
```

